create function pg_temp.football_actor(n integer,age integer default 1,ttl integer default 3600,service boolean default false) returns void language plpgsql as $$declare u text:='99969700-0000-4000-8000-'||lpad(n::text,12,'0');e bigint:=floor(extract(epoch from clock_timestamp()));begin
 perform set_config('request.jwt.claim.sub',case when service then '' else u end,true);perform set_config('request.jwt.claim.role',case when service then 'service_role' else 'authenticated' end,true);
 perform set_config('request.jwt.claims',case when service then '{"role":"service_role"}' else jsonb_build_object('sub',u,'role','authenticated','is_anonymous',false,'aal','aal2','exp',e+ttl,'session_id','99969700-0000-4000-8000-'||lpad((n+500)::text,12,'0'),'amr',jsonb_build_array(jsonb_build_object('method','totp','timestamp',e-age)))::text end,true);
end $$;
create temporary table football_receipts(k text primary key,v jsonb);grant select,insert,update on football_receipts to authenticated,service_role;
select ok(not exists(select 1 from unnest(array['manual_football_sync_commands','manual_football_sync_proofs','manual_football_sync_requests'])t cross join unnest(array['anon','authenticated','service_role'])r where has_table_privilege(r,'public.'||t,'SELECT,INSERT,UPDATE,DELETE')),'private original operations/proofs/provider barriers cannot be manufactured by app/service DML');
select ok(not exists(select 1 from unnest(array['public.manual_football_json_hash(jsonb)','public.manual_football_arguments(jsonb)','public.manual_football_snapshot()','public.manual_football_storage_recovery(public.manual_football_sync_commands)','public.guard_manual_football_immutable()','public.manual_football_receipt(public.manual_football_sync_commands)','public.lock_manual_football_sync_command(uuid)','public.assert_manual_football_authority(public.manual_football_sync_commands,uuid)','public.manual_football_url_decode(text)','public.assert_manual_football_request(public.manual_football_sync_commands,text)','public.manual_football_publication_target(public.manual_football_sync_commands,text,jsonb)','public.guard_manual_football_publication()'])f cross join unnest(array['anon','authenticated','service_role'])r where has_function_privilege(r,f,'EXECUTE')),'every private sync engine remains ungranted to app/service callers');
select ok(has_function_privilege('authenticated','public.admit_manual_football_sync(uuid,jsonb)','EXECUTE') and not has_function_privilege('service_role','public.admit_manual_football_sync(uuid,jsonb)','EXECUTE'),'only actual caller JWT admits an original GLOBAL operation');
select ok(has_function_privilege('service_role','public.start_manual_football_request(uuid,uuid,text)','EXECUTE') and not has_function_privilege('authenticated','public.start_manual_football_request(uuid,uuid,text)','EXECUTE'),'committed provider barriers are service-only');
select ok((select count(*)=3 from pg_policy where polrelid in('public.manual_football_sync_commands'::regclass,'public.manual_football_sync_proofs'::regclass,'public.manual_football_sync_requests'::regclass) and polname='account_lifecycle_access' and not polpermissive and polcmd='*'),'new private records retain canonical lifecycle protections');
select ok(to_regclass('football.prediction_friend_challenges') is null and to_regclass('retired.prediction_friend_challenges') is not null
 and not exists(select 1 from pg_proc where pronamespace='public'::regnamespace and proname='prediction_settle_fixture' and prosrc like '%prediction_settle_friend_challenges%'),
 'retired friend challenges remain preserved and unreachable from the active auto-settlement hook');
select ok(not exists(select 1 from unnest(array['public.football_sync_config','public.football_sync_log','football.competitions','football.seasons','football.teams','football.fixtures','football.standings','football.fixture_stats','football.fixture_events','football.fixture_lineups','football.fixture_lineup_players','storage.objects','storage.buckets','football.predict_pools','football.fixture_markets','football.predictions','football.prediction_settlements','football.prediction_slips','public.fan_memberships','public.fet_events','public.fet_wallet_ledger_entries'])t
 cross join unnest(array['manual_football_statement_guard','manual_football_row_guard'])n
 where (select relkind from pg_class where oid=t::regclass) not in('r','p') or not exists(select 1 from pg_trigger where tgrelid=t::regclass and tgname=n and not tgisinternal and tgfoid='public.guard_manual_football_publication()'::regprocedure)),
 'all21 actual physical/config/provider/financial publishers retain statement and backing-row original proof guards');
select ok((select relkind='v' from pg_class where oid='public.xp_events'::regclass)
 and exists(select 1 from pg_trigger where tgrelid='public.xp_events'::regclass and tgname='manual_football_statement_guard' and (tgtype::integer&1)=0 and (tgtype::integer&2)=2 and tgfoid='public.guard_manual_football_publication()'::regprocedure)
 and exists(select 1 from pg_trigger where tgrelid='public.xp_events'::regclass and tgname='trg_xp_events_compat_write' and (tgtype::integer&64)=64 and tgfoid='public.xp_events_compat_write()'::regprocedure),
 'xp_events preserves its actual statement guard and original INSTEAD OF backing-table writer');
