select is((select v->>'content_sha256' from football_receipts where k='logo-put'),'039058c6f2c0cb492c533b0a4d14ef77cc0f78abccced5287d84a1a2011cfb81','original byte SHA is durable before any Storage PUT');
select is((select(v->>'byte_length')::integer from football_receipts where k='logo-put'),3,'original byte length is durable before Storage PUT');
select is((select v->>'content_type' from football_receipts where k='logo-put'),'image/png','original content type is durable before Storage PUT');
select throws_ok($$insert into storage.objects(bucket_id,name,version,metadata,user_metadata) values('football-assets','teams/199697.png','qa-1','{"size":3,"mimetype":"image/png"}',jsonb_build_object('manual_football_operation','99969700-0000-4000-8000-000000000705','manual_football_lease','99969700-0000-4000-8000-000000000805','manual_football_proof',(select v->>'dispatch_proof_id' from football_receipts where k='logo-admission'),'manual_football_request',(select v->>'request_id' from football_receipts where k='logo-put'),'content_sha256','wrong'))$$,'42501','FOOTBALL_STORAGE_BINDING_MISMATCH','forged object metadata cannot manufacture original bytes');
select lives_ok($$insert into storage.objects(bucket_id,name,version,metadata,user_metadata) values('football-assets','teams/199697.png','qa-1','{"size":3,"mimetype":"image/png"}',jsonb_build_object('manual_football_operation','99969700-0000-4000-8000-000000000705','manual_football_lease','99969700-0000-4000-8000-000000000805','manual_football_proof',(select v->>'dispatch_proof_id' from football_receipts where k='logo-admission'),'manual_football_request',(select v->>'request_id' from football_receipts where k='logo-put'),'content_sha256',(select v->>'content_sha256' from football_receipts where k='logo-put')))$$,'actual service Storage row binds original operation/request/lease/proof/body without HTTP headers');
select public.complete_manual_football_request('99969700-0000-4000-8000-000000000705','99969700-0000-4000-8000-000000000805',(select(v->>'request_id')::uuid from football_receipts where k='logo-put'),null,'{}',null);
select public.finish_manual_football_sync('99969700-0000-4000-8000-000000000705','99969700-0000-4000-8000-000000000805','{"success":false}');
reset role;select pg_temp.football_actor(1);set local role authenticated;
insert into football_receipts values('logo-review',public.admit_manual_football_sync('99969700-0000-4000-8000-000000000705','{"command":"download-logos"}'));
reset role;select pg_temp.football_actor(1,1,3600,true);set local role service_role;
insert into football_receipts values('logo-reconcile',public.claim_manual_football_sync('99969700-0000-4000-8000-000000000705','99969700-0000-4000-8000-000000000806',(select(v->>'dispatch_proof_id')::uuid from football_receipts where k='logo-review')));
select is((select v->>'mode' from football_receipts where k='logo-reconcile'),'reconcile_storage','fresh explicit review leases only original unknown Storage readback');
select throws_ok($$select public.start_manual_football_request('99969700-0000-4000-8000-000000000705','99969700-0000-4000-8000-000000000806','https://media.api-sports.io/football/teams/199697.png')$$,'42501','FOOTBALL_RECONCILIATION_READ_ONLY','fresh recovery cannot repeat provider GET or upload');
select set_config('request.headers',jsonb_build_object('x-africlub-football-operation','99969700-0000-4000-8000-000000000705','x-africlub-football-lease','99969700-0000-4000-8000-000000000806','x-africlub-football-proof',(select v->>'dispatch_proof_id' from football_receipts where k='logo-review'))::text,true);
select throws_ok($$update public.football_sync_config set last_synced_at=clock_timestamp() where id='99969700-0000-4000-8000-000000000601'$$,'42501','FOOTBALL_RECONCILIATION_READ_ONLY','fresh readback cannot authorize public progress/config mutation');
select set_config('request.headers','{}',true);
select throws_ok($$select public.complete_manual_football_request('99969700-0000-4000-8000-000000000705','99969700-0000-4000-8000-000000000806',(select(v->>'request_id')::uuid from football_receipts where k='logo-put'),null,'{}',null)$$,'42501','FOOTBALL_REQUEST_LEASE_LOST','readback requires an actual verified known body and cannot record another unknown upload');
select throws_ok($$select public.complete_manual_football_request('99969700-0000-4000-8000-000000000705','99969700-0000-4000-8000-000000000805',(select(v->>'request_id')::uuid from football_receipts where k='logo-put'),200,'{"content-type":"image/png"}',encode(decode('010203','hex'),'base64'))$$,'42501','FOOTBALL_LEASE_LOST','original worker cannot borrow newer readback assurance');
select throws_ok($$select public.complete_manual_football_request('99969700-0000-4000-8000-000000000705','99969700-0000-4000-8000-000000000806',(select(v->>'request_id')::uuid from football_receipts where k='logo-put'),200,'{"content-type":"image/png"}',encode(decode('030201','hex'),'base64'))$$,'22023','FOOTBALL_STORAGE_BYTES_MISMATCH','different downloaded bytes cannot manufacture original completion');
select lives_ok($$select public.complete_manual_football_request('99969700-0000-4000-8000-000000000705','99969700-0000-4000-8000-000000000806',(select(v->>'request_id')::uuid from football_receipts where k='logo-put'),200,'{"content-type":"image/png"}',encode(decode('010203','hex'),'base64'))$$,'actual original object metadata plus exact downloaded body reconciles original unknown upload');
select is(public.finish_manual_football_sync('99969700-0000-4000-8000-000000000705','99969700-0000-4000-8000-000000000806','{"success":false,"data":{"reconciled_storage_count":1}}')->'command'->>'state','completed','recovery records known original outcome without invented whole-sync success');
reset role;
select is((select count(*)::integer from public.manual_football_sync_requests where operation_id='99969700-0000-4000-8000-000000000705'),2,'readback created zero provider/Storage request attempts');
select ok(not exists(select 1 from pg_constraint c where c.contype='f' and c.confrelid in('auth.users'::regclass,'public.users'::regclass,'public.profiles'::regclass) and not exists(select 1 from public.account_erasure_fk_inventory i where i.constraint_oid=c.oid and i.child_table=c.conrelid::regclass::text and i.subject_table=c.confrelid::regclass::text and i.deletion_action=c.confdeltype::text)),'all current Auth/subject retained FK identities remain inventoried');
select * from finish();rollback;
